effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  vec3 base = mono ? vec3(gmLum(c)) : c;
  base = clamp((base - 0.5) * contrast + 0.5, 0.0, 1.0);
  float rad = radians(angle);
  vec2 rp = vec2(uv.x * cos(rad) - uv.y * sin(rad), uv.x * sin(rad) + uv.y * cos(rad));
  vec2 cell = fract(rp * scale) - 0.5;
  float d = length(cell);
  vec3 dots;
  dots.r = step(d, sqrt(base.r) * 0.5);
  dots.g = step(d, sqrt(base.g) * 0.5);
  dots.b = step(d, sqrt(base.b) * 0.5);
  vec3 col = mix(c, dots, mixAmt);
  gl_FragColor = vec4(col * a, a);
}
